const steps=lessons.flatMap((l,i)=>l.steps.map((x,j)=>({key:x[0],title:x[1],desc:x[2],target:x[3],lesson:i,part:j+1}))),at=key=>steps.findIndex(x=>x.key===key);
function emptyDraft(){return {surname:'',given:'',email:'',birth:'',gender:'M',grade:'',class:'',number:'',consent:'',method:'phone',contact:'',agree:null,use:true};}
function student(id,surname,given,email,number,use=true){return {id,surname,given,email:email+DOMAIN,birth:'2016-05-10',gender:'M',grade:'4',class:'2',number:String(number),consent:'연습용_동의서.pdf',method:'phone',contact:'01000000000',agree:true,use,joined:'2026.10.15 09:00',transferred:false};}
function initial(){return {schemaVersion:2,step:0,page:'dashboard',students:[student('s1','김','가온','go.kim12',1),student('s2','이','다온','do.lee23',2),student('s3','박','하람','hr.park34',3),student('s4','최','라온','ro.choi45',4,false)],draft:emptyDraft(),detailId:null,editing:false,query:'',queried:false,filters:{grade:'',class:'',number:'',keyword:'',use:'',by:'name',from:'',to:''},applied:{},selected:[],force:false,hints:true,modal:null,bulk:[],bulkConsent:false,bulkFile:'',fileError:'',downloads:[],deleteReason:'',deleteAgreed:false,expanded:true};}
const legacyStepKeys=steps.flatMap(s=>s.key==='agree'?['consent','method','contact','agree']:[s.key]);
function migrateSaved(saved){const s={...saved};if(s.schemaVersion!==2){const mapStep=n=>n>=legacyStepKeys.length?steps.length:Math.max(0,at(['consent','method','contact'].includes(legacyStepKeys[n])?'agree':legacyStepKeys[n]));s.step=mapStep(s.step);const fixModal=m=>{if(!m)return m;const copy={...m};if(Number.isInteger(copy.returnStep))copy.returnStep=mapStep(copy.returnStep);if(copy.previous)copy.previous=fixModal(copy.previous);return copy;};s.modal=fixModal(s.modal);}else if(s.progressKey){s.step=s.progressKey==='complete'?steps.length:Math.max(0,at(s.progressKey));}s.schemaVersion=2;return s;}
let state=initial();try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Number.isInteger(s.step)&&s.step>=0&&s.step<=legacyStepKeys.length&&Array.isArray(s.students))state={...state,...migrateSaved(s)};}catch(e){}
function save(){state.schemaVersion=2;state.progressKey=cur()?.key||'complete';try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}
function cur(){return steps[state.step];}function is(key){return cur()?.key===key;}
let toastTimer;function toast(t){$('toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',4000);}
function guard(key){if(is(key))return true;toast('현재 미션: '+(cur()?.title||'실습을 완료했습니다.'));return false;}
function next(){state.step++;save();render();}
function highlight(){document.querySelectorAll('.focus-target').forEach(x=>x.classList.remove('focus-target'));if(cur())$(cur().target)?.classList.add('focus-target');document.body.classList.toggle('no-hints',!state.hints);$('hint-toggle').textContent=state.hints?'노란색 안내 켜짐':'노란색 안내 꺼짐';$('hint-toggle').setAttribute('aria-pressed',String(state.hints));}
function guide(){const done=!cur(),i=cur()?.lesson??lessons.length,percent=Math.round(state.step/steps.length*100);$('progress-text').textContent=done?`${lessons.length} / ${lessons.length} 완료`:`${i+1} / ${lessons.length} 미션 · ${percent}%`;$('progress-fill').style.width=percent+'%';$('progress').setAttribute('aria-valuenow',percent);$('missions').innerHTML=lessons.map((l,j)=>`<li class="mission ${j<i?'done':j===i?'current':''}"><div class="num">${j<i?'✓':j+1}</div><div><strong>${l.title}</strong><small>${l.desc}</small></div></li>`).join('');$('task-eyebrow').textContent=done?'PRACTICE COMPLETE':`MISSION ${i+1} · STEP ${cur().part}/${lessons[i].steps.length}`;$('task-title').textContent=done?'학생 회원 관리 실습 완료!':cur().title;$('task-desc').innerHTML=done?'개별·일괄 등록과 학생 계정 관리 절차를 모두 연습했습니다.':cur().desc;}
function pageTitle(t='학생 회원 관리'){return `<div class="page-title"><h2>${t}</h2><div class="breadcrumbs">⌂　›　회원 관리　›　학생 회원 관리</div></div>`;}
function shell(){return `<div class="admin-top"><div class="seoul-logo">✣ 서울특별시교육청</div><div class="account"><span class="avatar">♙</span><div><strong>학교관리자</strong><br><span class="email">school.admin@example.com</span></div></div></div><div class="admin-body"><nav class="nav"><button class="nav-group" data-action="expand"><span>▣ &nbsp;회원 관리</span><span>${state.expanded?'⌃':'⌄'}</span></button>${state.expanded?`<div class="nav-sub"><a href="index.html" class="nav-student-link">교사 승인 관리</a><a href="index.html" class="nav-student-link">교사 반려 관리</a><a href="index.html" class="nav-student-link">교사 회원 관리</a><button class="${state.page!=='dashboard'?'active':''}" id="nav-students" data-action="nav">학생 회원 관리</button><a class="nav-student-link" href="academic.html">학적관리</a></div>`:''}<button class="other-nav" data-action="outside">▤ &nbsp;학교 관리</button><button class="other-nav" data-action="outside">▧ &nbsp;단말 관리</button><button class="other-nav" data-action="outside">▤ &nbsp;구매에듀테크 관리</button><button class="other-nav" data-action="outside">▤ &nbsp;학사정보 관리 이동</button></nav><div class="content">${state.page==='dashboard'?`<div class="dashboard st-dashboard"><div class="welcome-icon">♙</div><h3>${SCHOOL}</h3><p>학교관리자로 접속한 상태입니다.<br>왼쪽 ‘학생 회원 관리’에서 실습을 시작하세요.</p></div>`:state.page==='list'?list():state.page==='bulk'?bulkPage():formPage()}</div></div>`;}
function name(t){return t.surname+t.given;}
function filtered(){if(!state.queried)return[];const f=state.applied;return state.students.filter(t=>!t.transferred&&!t.deleted&&(!f.grade||t.grade===f.grade)&&(!f.class||t.class===f.class)&&(!f.number||t.number===f.number)&&(!f.use||(f.use==='used'?t.use:!t.use))&&(!f.keyword||(f.by==='email'?t.email:name(t)).includes(f.keyword))&&(!f.from||t.joined.slice(0,10).replaceAll('.','-')>=f.from)&&(!f.to||t.joined.slice(0,10).replaceAll('.','-')<=f.to));}
function selectOptions(value,options){return options.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('');}
function filters(){const f=state.filters;return `<div class="filter-card st-filter"><div class="filter-row"><label>소속</label><strong>${SCHOOL}</strong></div><div class="filter-row"><label>학적정보</label><span>학년</span><select id="st-filter-grade" data-filter="grade" aria-label="검색 학년">${selectOptions(f.grade,[['','학년 전체'],...[1,2,3,4,5,6].map(n=>[n,n+'학년'])])}</select><span>반</span><input class="mini" data-filter="class" aria-label="검색 반" value="${esc(f.class)}"><span>번호</span><input class="mini" data-filter="number" aria-label="검색 번호" value="${esc(f.number)}"></div><div class="filter-row"><label>가입기간</label><input type="date" data-filter="from" aria-label="가입기간 시작" value="${f.from}"> ~ <input type="date" data-filter="to" aria-label="가입기간 종료" value="${f.to}"><div class="date-shortcuts">${[['today','오늘'],['month','1개월'],['quarter','3개월'],['half','6개월'],['all','직접입력']].map(([v,t])=>`<button data-action="date-${v}">${t}</button>`).join('')}</div></div><div class="filter-row"><label for="st-keyword">검색어</label><select data-filter="by" aria-label="검색 기준">${selectOptions(f.by,[['name','이름'],['email','아이디']])}</select><input class="keyword" id="st-keyword" data-filter="keyword" aria-label="학생 검색어" value="${esc(f.keyword)}" autocomplete="off"></div><div class="filter-row"><label for="st-use-filter">사용이력</label><select id="st-use-filter" data-filter="use">${selectOptions(f.use,[['','전체'],['used','사용'],['unused','미사용']])}</select><span class="st-note">미사용 학생 계정은 조회 후 삭제할 수 있습니다.</span><button class="small" data-action="clear">초기화</button><button class="small dark" id="st-search" data-action="search">⌕ 검색</button></div></div>`;}
function list(){const rows=filtered();return `${pageTitle()}${filters()}<div class="table-bar st-tablebar"><strong>전체 ${rows.length}${state.selected.length?` · 선택 ${state.selected.length}명`:''}</strong><div class="st-actions"><button id="st-transfer" data-action="transfer">일괄 전출처리</button><label class="check-wrap" id="force-change"><input type="checkbox" data-change="force" aria-label="사용자가 로그인 시 비밀번호 변경 설정" ${state.force?'checked':''}></label><span class="st-note">사용자가 로그인 시 비밀번호 변경 설정</span><button id="st-pw-bulk" data-action="pw-bulk">비밀번호 일괄 변경</button><button id="st-export" data-action="export">엑셀다운로드</button><button id="st-bulk" data-action="bulk">일괄 등록</button><button class="primary" id="st-new" data-action="new">회원 등록</button>${state.queried&&state.applied.use==='unused'?'<button class="st-danger" id="st-delete" data-action="delete">회원 삭제</button>':''}</div></div><div class="table-scroll"><table class="student-table"><thead><tr><th><input type="checkbox" data-change="all" aria-label="현재 조회 학생 전체 선택"></th><th>NO</th><th>사용이력</th><th>소속명</th><th>학년</th><th>반</th><th>번호</th><th>이름</th><th>아이디</th><th>가입일시</th></tr></thead><tbody>${rows.map((t,i)=>`<tr><td><label class="check-wrap" id="st-check-${t.id}"><input type="checkbox" data-select="${t.id}" aria-label="${name(t)} 선택" ${state.selected.includes(t.id)?'checked':''}></label></td><td>${i+1}</td><td>${t.use?'사용':'미사용'}</td><td>${SCHOOL}</td><td>${t.grade}</td><td>${t.class}</td><td>${t.number}</td><td><button class="link-btn" id="st-name-${t.id}" data-action="detail" data-id="${t.id}">${esc(name(t))}</button></td><td><button class="link-btn" data-action="detail" data-id="${t.id}">${esc(t.email)}</button></td><td>${t.joined}</td></tr>`).join('')||`<tr><td colspan="10" class="empty">${state.queried?'조회된 학생이 없습니다.':'검색 버튼을 클릭해 학생 목록을 조회하세요.'}</td></tr>`}</tbody></table></div><div class="paging"><div><button data-action="one-page">‹</button> 1 <button data-action="one-page">›</button></div><span>10개씩 보기</span></div>`;}
function field(label,value,required=false){return `<div class="term">${label}${required?' <span class="required">•</span>':''}</div><div>${value}</div>`;}
function input(id,key,value,type='text',narrow=false){return `<input type="${type}" id="${id}" data-draft="${key}" value="${esc(value)}" aria-label="${{surname:'성',given:'이름',birth:'생년월일',class:'반',number:'번호',contact:'알림 연락처'}[key]||key}" ${narrow?'class="narrow"':''} autocomplete="off">`;}
function formPage(){const d=state.draft,editing=state.page==='new'||state.editing,creating=state.page==='new';return `<div class="member-detail st-form">${pageTitle()}<div class="section-title"><span>회원정보</span>${!editing?'<button class="small primary" id="st-edit" data-action="edit">수정</button>':''}</div><div class="info-section"><div class="st-topline"><h3>기본정보</h3>${editing?'<button class="primary small" id="st-save" data-action="save">저장</button>':''}</div><div class="detail-grid">${editing?field('성',`<div class="name-pair">${input('st-surname','surname',d.surname)}<span>이름 <span class="required">•</span></span>${input('st-given','given',d.given)}</div>`,true):field('이름',esc(name(d)))}${field('아이디',creating?`<div class="id-line"><div><div class="${d.email?'generated-id':'id-copy'}">${d.email?esc(d.email):'아이디 생성 버튼을 클릭하여 아이디를 생성해 주세요.'}</div><p class="id-rule">이름 이니셜.성+숫자${DOMAIN} 형식으로 자동 생성</p></div><button class="primary" id="${d.email?'st-id-edit':'st-generate'}" data-action="${d.email?'id-edit':'generate'}">${d.email?'아이디 수정':'아이디 생성'}</button></div>`:esc(d.email),creating)}${field('생년월일',editing?input('st-birth','birth',d.birth,'date',true):esc(d.birth),editing)}${field('성별',editing?`<div class="radios"><label><input type="radio" name="st-gender" data-draft="gender" value="M" ${d.gender==='M'?'checked':''}>남자</label><label id="st-female"><input type="radio" name="st-gender" data-draft="gender" value="F" ${d.gender==='F'?'checked':''}>여자</label></div>`:d.gender==='F'?'여자':'남자',editing)}${!creating&&editing?field('비밀번호','<button class="small" id="st-pw" data-action="pw-single">비밀번호 변경</button>'):''}</div></div><div class="info-section"><h3>부가정보</h3><div class="detail-grid">${field('소속구분','학교')}${field('소속학교',SCHOOL,editing)}${field('학년',editing?`<select id="st-grade" data-draft="grade" aria-label="학년">${selectOptions(d.grade,[['','선택'],...[1,2,3,4,5,6].map(n=>[n,n+'학년'])])}</select>`:d.grade+'학년',editing)}${field('반',editing?input('st-class','class',d.class,'text',true):esc(d.class),editing)}${field('번호',editing?input('st-number','number',d.number,'text',true):esc(d.number),editing)}${field('개인정보 활용 동의서',esc(d.consent||'첨부 없음'))}${field('알림 수신 방식',`${d.method==='email'?'이메일':'휴대전화'}${d.contact?' | '+esc(d.contact):''}`)}${field('알림 수신 동의',editing?`<div class="radios"><label id="st-agree-yes"><input type="radio" name="st-agree" data-draft="agree" value="yes" ${d.agree===true?'checked':''}>동의함</label><label><input type="radio" name="st-agree" data-draft="agree" value="no" ${d.agree===false?'checked':''}>동의안함</label></div>`:d.agree?'Y':'N')}${!creating?field('사용여부',editing?`<div class="radios"><label><input type="radio" name="st-use" data-draft="use" value="yes" ${d.use?'checked':''}>사용</label><label><input type="radio" name="st-use" data-draft="use" value="no" ${!d.use?'checked':''}>미사용</label></div>`:d.use?'사용':'미사용'):''}</div></div><div class="detail-bottom"><button id="st-back" data-action="back">목록</button><button class="primary" data-action="${editing?'save':'edit'}">${editing?'저장':'수정'}</button></div>${!editing?`<div class="info-section history-section"><h3>회원정보 수정이력</h3><div class="st-mini-summary">${d.modified?'2026.10.18 10:10 · 학교관리자 · 반 정보 및 비밀번호 변경':'조회된 수정이력이 없습니다.'}</div></div>`:''}</div>`;}
const bulkHeaders=['순번','학년','반','번호','성','이름','전체이름','성별','생년월일','개인정보동의첨부파일제출여부','휴대전화번호','알림수신이메일','법정대리인명','법정대리인휴대전화번호'];
const practiceRows=[['1','4','2','22','조','수아','조수아','여자','20160411','Y','01000000000','','가상보호자1','01000000000'],['2','4','2','23','정','하준','정하준','남자','20160621','Y','01000000000','','가상보호자2','01000000000'],['3','4','2','24','최','지우','최지우','여자','20160709','Y','01000000000','','가상보호자3','01000000000']];
function bulkPage(){return `${pageTitle()}<div class="st-topline"><p class="st-note">학생 일괄등록 양식 파일을 작성 후 등록하여 학생을 일괄등록합니다.</p><span class="subtle">학생 일괄등록 양식 다운로드</span></div><div class="bulk-card"><h3>학생의 회원(학적) 정보를 일괄 등록합니다.</h3><p>학생의 회원정보를 등록하려면 학생 또는 법정대리인의 개인정보 활용 동의가 필요합니다.<br>동의서는 학생정보 관리에 포함되며 학교에서 관리합니다.</p><p class="blue">학생 정보는 사전 동의 후 등록해 주시기 바랍니다.</p><b>학생 일괄 등록 순서</b><ol><li>파일 검색: 등록 대상 파일 선택 후 업로드</li><li>아이디 생성: 등록 대상 학생의 아이디 일괄 부여</li><li>등록: 학생 계정 일괄등록 최종 저장</li></ol><div class="bulk-downloads"><a class="bulk-download-link" id="bulk-template" href="downloads/student-template.xlsx" download="학생_일괄등록_양식.xlsx" data-action="template">학생 일괄등록 양식 다운로드 ↓</a><a class="bulk-download-link" id="bulk-sample" href="downloads/student-practice.xlsx" download="학생_일괄등록_연습.xlsx" data-action="sample">작성된 연습용 파일 다운로드 ↓</a></div><div class="bulk-consent"><label id="bulk-consent"><input type="checkbox" data-change="bulk-consent" ${state.bulkConsent?'checked':''}>학생 개인정보 활용 안내 확인 및 동의</label></div><div class="bulk-upload"><label for="bulk-file">학생 일괄등록 양식</label><input id="bulk-file" class="file-input" aria-label="파일 검색" type="file" accept=".xlsx,.csv"><button class="primary" id="bulk-generate" data-action="bulk-generate">⌕ 아이디 생성</button><button class="small" id="bulk-load-demo" data-action="load-demo">파일 선택 없이 연습 명단 불러오기</button></div>${state.bulkFile?`<div class="st-note">선택한 파일: ${esc(state.bulkFile)}</div>`:''}<div class="bulk-error" id="bulk-error" role="alert">${esc(state.fileError)}</div></div><div class="table-bar"><strong>전체 ${state.bulk.length}</strong></div><div class="table-scroll"><table class="bulk-table"><thead><tr><th>NO</th><th>학생 중복 확인</th><th>학년</th><th>반</th><th>번호</th><th>이름</th><th>성별</th><th>아이디</th><th>아이디수정</th><th>생년월일</th></tr></thead><tbody>${state.bulk.map((t,i)=>`<tr><td>${i+1}</td><td>${t.email?'확인 완료':'확인 전'}</td><td>${t.grade}</td><td>${t.class}</td><td>${t.number}</td><td>${esc(name(t))}</td><td>${t.gender==='M'?'남자':'여자'}</td><td>${esc(t.email||'')}</td><td>${t.email?`<button class="small primary" id="bulk-edit-${t.id}" data-action="bulk-id-edit" data-id="${t.id}">수정하기</button>`:''}</td><td>${t.birth}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">학생 일괄등록 파일을 선택해 주세요.</td></tr>'}</tbody></table></div><div class="bulk-note">학생 계정의 초기 비밀번호는 <b>아이디(도메인 제외)+학년+번호</b>로 생성됩니다.<br>예: ms.kim1234@senedu.kr · 4학년 21번 → <b>ms.kim1234421</b></div><div class="bulk-bottom"><button data-action="outside">목록</button><button class="primary" id="bulk-register" data-action="bulk-register">등록</button></div>`;}
const surnames={'김':'kim','이':'lee','박':'park','최':'choi','정':'jeong','강':'kang','조':'jo','윤':'yoon','장':'jang','임':'lim','한':'han','오':'oh','서':'seo','신':'shin','권':'kwon','황':'hwang','안':'ahn','송':'song','전':'jeon','홍':'hong','유':'yoo','고':'ko','문':'moon','양':'yang','손':'son','배':'bae','백':'baek','허':'heo','남':'nam','심':'shim','노':'noh','하':'ha','주':'joo','우':'woo','구':'koo','민':'min','진':'jin','지':'ji','엄':'eom','채':'chae','원':'won','천':'cheon','방':'bang','공':'gong','현':'hyun','함':'ham','변':'byun','여':'yeo','추':'chu','도':'do','소':'so','석':'seok','선':'seon','설':'seol','마':'ma','길':'gil','연':'yeon','성':'seong','차':'cha','류':'ryu','나':'na','남궁':'namgung','제갈':'jegal','선우':'seonwoo','사공':'sagong'};
function romanize(text){const on=['g','kk','n','d','tt','r','m','b','pp','s','ss','','j','jj','ch','k','t','p','h'],vow=['a','ae','ya','yae','eo','e','yeo','ye','o','wa','wae','oe','yo','u','wo','we','wi','yu','eu','ui','i'],end=['','k','k','ks','n','nj','nh','t','l','lk','lm','lb','ls','lt','lp','lh','m','p','ps','t','t','ng','t','t','k','t','p','h'];return [...text].map(c=>{const n=c.charCodeAt(0)-0xac00;if(n<0||n>11171)return c.toLowerCase().replace(/[^a-z]/g,'');return on[Math.floor(n/588)]+vow[Math.floor(n%588/28)]+end[n%28];}).join('');}
function idBase(surname,given){const sn=surnames[surname.trim()]||romanize(surname.trim()),parts=/[가-힣]/.test(given)?[...given.trim()]:given.trim().split(/[\s-]+/);const initials=parts.map(p=>romanize(p).charAt(0)).join('');if(!sn||!initials)throw Error('성·이름을 한글 또는 영문으로 입력해 주세요.');return initials+'.'+sn;}
function uniqueEmail(base,exclude=''){if(!/^[a-z]+\.[a-z]+$/.test(base))throw Error('숫자·도메인 없이 영문 이니셜.성 형식으로 입력해 주세요.');const existing=new Set([...state.students,...state.bulk].filter(t=>t.id!==exclude).map(t=>t.email));for(let i=0;i<10000;i++){const nums=new Uint32Array(1);crypto.getRandomValues(nums);const email=base+(nums[0]%9999+1)+DOMAIN;if(!existing.has(email)&&email!==state.draft.email&&email!==state.modal?.oldEmail)return email;}throw Error('아이디 생성에 실패했습니다. 다시 시도해 주세요.');}
function validDraft(d){if(!d.surname.trim()||!d.given.trim()||!d.email)return '성·이름과 생성한 아이디를 확인하세요.';if(!/^\d{4}-\d{2}-\d{2}$/.test(d.birth)||!validBirth(d.birth))return '생년월일을 확인하세요.';if(!/^[1-6]$/.test(d.grade)||!/^\d+$/.test(d.class)||Number(d.class)<1||!/^\d+$/.test(d.number)||Number(d.number)<1)return '학년·반·번호를 확인하세요.';if(d.agree===null)return '알림 수신 동의 여부를 선택하세요.';return '';}
function validBirth(s){const date=new Date(s+'T00:00:00Z');return !isNaN(date)&&date.toISOString().slice(0,10)===s&&s<'2026-10-19';}
function passwordError(value,check){if(value.length<10||value.length>20)return '비밀번호는 10~20자로 입력해 주세요.';if(!/^[A-Za-z0-9!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~]+$/.test(value))return '영문·숫자·허용 특수문자로 입력해 주세요.';if(value!==check)return '두 비밀번호가 일치하지 않습니다.';return '';}
function openModal(m,advance=true){state.modal={...m,returnStep:state.step};if(advance)next();else{save();renderModal();highlight();}}
function success(title,text,key,after){openModal({kind:'success',title,text,key,after});}
function renderModal(){const m=state.modal;if(!m){$('modal-root').innerHTML='';return;}let body='',buttons='';if(m.kind==='id'){body=`<div class="id-dialog-content"><p class="id-intro">학생의 아이디를 수정합니다.<br>수정 하시겠습니까?</p><div class="id-rules" id="id-rules"><div>아래의 아이디 규칙으로만 수정 가능합니다.<strong>(숫자 입력 불가)</strong></div><div class="id-rule-row"><span class="info-symbol" aria-hidden="true">i</span><span>한글: 이름 2글자 이니셜+'.'+성 한글자를 영문으로 변환　ex) 김수정 → sj.kim</span></div><div class="id-rule-row"><span class="info-symbol" aria-hidden="true">i</span><span>영문: 이름 앞 2글자+'.'+성 앞 3글자　ex) Smith James → ja.smi</span></div></div><div class="id-data-row"><span>변경전 아이디:</span><span>${esc(m.oldEmail?.split('@')[0]||'')}</span></div><div class="id-data-row id-entry-row"><label for="id-base">변경아이디 입력:</label><div class="id-entry-controls"><input id="id-base" data-modal="base" value="${esc(m.base||'')}" placeholder="변경할 아이디를 입력해주세요." aria-describedby="id-rules modal-error" autocomplete="off" autocapitalize="none" spellcheck="false"><button class="primary" id="id-assign" data-action="id-assign">번호 채번</button></div></div><div class="id-assigned-note" id="id-assigned-note" role="status">${m.result?'✓ 채번 후 아이디 생성이 완료되었습니다.':''}</div><div class="id-data-row id-result-row"><span>변경후 아이디:</span><span id="id-result">${esc(m.result?.split('@')[0]||'')}</span></div></div>`;buttons=`<button data-action="modal-cancel">취소</button><button class="primary" id="id-apply" data-action="id-apply">적용</button>`;}else if(m.kind==='password'){body=`<p>${m.bulk?'선택한 학생 2명':'김민서 학생'}의 비밀번호를 변경합니다.</p><div class="form-field"><label for="password-value">변경할 비밀번호</label><input type="password" id="password-value" data-action="fill-password" data-modal="password" readonly aria-label="변경할 비밀번호, 클릭하면 자동 입력" placeholder="클릭하면 비밀번호가 입력됩니다" autocomplete="off" value="${esc(m.password||'')}"></div><div class="form-field"><label for="password-check">변경 비밀번호 확인</label><input type="password" id="password-check" data-action="fill-password-check" data-modal="passwordCheck" readonly aria-label="비밀번호 확인, 클릭하면 자동 입력" placeholder="클릭하면 같은 비밀번호가 입력됩니다" autocomplete="off" value="${esc(m.passwordCheck||'')}"></div><small>영문 대소문자, 숫자, 특수문자 구분 없이 10~20자 입력 가능<br>두 입력란을 차례로 클릭하면 실습용 비밀번호가 자동 입력됩니다.</small>${m.bulk&&state.force?'<div class="mini-confirm">다음 로그인 시 비밀번호 변경: 설정</div>':''}`;buttons='<button data-action="modal-cancel">취소</button><button class="primary" id="password-submit" data-action="password-submit">비밀번호 변경</button>';}else if(m.kind==='delete'){body='<p>미사용 가상 계정을 삭제합니다.<br>실제 시스템에서는 삭제한 계정과 데이터는 복구할 수 없습니다.</p><div class="form-field"><label for="delete-reason">삭제 사유 (직접 입력)</label><textarea id="delete-reason" data-modal="deleteReason" maxlength="50" rows="3">'+esc(state.deleteReason)+'</textarea></div><small>선택한 학생: 최라온 · 최대 50자</small><label class="check-label" id="delete-agree"><input type="checkbox" data-change="delete-agree" '+(state.deleteAgreed?'checked':'')+'>안내를 읽었으며 삭제에 동의합니다.</label>';buttons='<button data-action="modal-cancel">취소</button><button class="primary" id="delete-submit" data-action="delete-submit">동의 및 확인</button>';}else{body=`<p>${esc(m.text).replace(/\n/g,'<br>')}</p>`;buttons=(m.kind==='confirm'?'<button data-action="modal-cancel">취소</button>':'')+'<button class="primary" id="modal-confirm" data-action="modal-confirm">확인</button>';}
$('modal-root').innerHTML=m.kind==='confirm'&&m.operation==='transfer'?`<div class="overlay"><div class="modal student-modal transfer-dialog" role="dialog" aria-modal="true" aria-label="일괄 전출처리 확인" aria-describedby="transfer-message"><p id="transfer-message">선택된 ${m.count??state.selected.length}명의 학생을 전출처리하시겠습니까?</p><div class="modal-actions"><button data-action="modal-cancel">취소</button><button class="primary" id="modal-confirm" data-action="modal-confirm">확인</button></div></div></div>`:m.kind==='id'?`<div class="overlay id-dialog-overlay"><div class="modal student-modal id-edit-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="id-dialog-header"><h2 id="modal-title">아이디 수정</h2><button class="id-dialog-close" data-action="modal-cancel" aria-label="아이디 수정 창 닫기">×</button></div>${body}<div class="modal-error" id="modal-error" role="alert"></div><div class="modal-actions id-dialog-actions">${buttons}</div></div></div>`:`<div class="overlay"><div class="modal student-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-icon">${m.kind==='success'?'✓':m.kind==='restart'?'↻':'?'}</div><h2 id="modal-title">${esc(m.title)}</h2>${body}<div class="modal-error" id="modal-error" role="alert"></div><div class="modal-actions">${buttons}</div></div></div>`;queueMicrotask(()=>{const target=cur()&&$(cur().target);if(target&&$('modal-root').contains(target))target.focus({preventScroll:true});else $('modal-confirm')?.focus({preventScroll:true});});}
function finish(){return `<div class="course-complete"><div class="checkmark">✓</div><div class="guide-kicker">ALL MISSIONS COMPLETED</div><h2>학생 계정 관리,<br>직접 해냈어요.</h2><p>${SCHOOL}의 가상 학생으로<br>${lessons.length}개 미션을 모두 완료했습니다.</p><div class="summary-tags">${['개별 등록·아이디 생성','일괄 등록·아이디 수정','학생 회원정보 수정','개별·일괄 비밀번호 변경','엑셀다운로드','일괄 전출처리','미사용 회원 삭제'].map(t=>`<span>✓ ${t}</span>`).join('')}</div><button class="primary" data-action="restart-now">학생 실습 다시 하기 ↻</button><a class="course-tab" href="academic.html">학적관리 실습으로 이동 →</a><a class="course-tab" href="index.html">교사 실습으로 이동</a></div>`;}
function render(){guide();$('screen').innerHTML=cur()?shell():finish();renderModal();highlight();}
function inputNext(){save();guide();highlight();}
function expectedInput(id,value){const key=cur()?.key,go={surname:['st-surname','김'],given:['st-given','민서'],birth:['st-birth','2016-03-15'],grade:['st-grade','4'],class:['st-class','2'],number:['st-number','21'],'id-base':['id-base','ms.kim'],'bulk-id-base':['id-base','sa.jo'],'find-name':['st-keyword','김민서'],'edit-class':['st-class','3'],'pw-value':['password-value','Practice123!'],'pw-check':['password-check','Practice123!'],'bulk-pw-value':['password-value','Practice456!'],'bulk-pw-check':['password-check','Practice456!']};if(go[key]&&go[key][0]===id&&String(value).trim()===go[key][1]){state.step++;inputNext();}if(key==='delete-reason'&&id==='delete-reason'&&String(value).trim().length>=5){state.step++;inputNext();}}
function clearFilters(){state.filters={grade:'',class:'',number:'',keyword:'',use:'',by:'name',from:'',to:''};state.applied={};state.selected=[];}
function runSearch(){if(is('find-search')&&state.filters.keyword.trim()!=='김민서'){toast('이름 김민서를 입력하세요.');return;}if(is('unused-search')&&state.filters.use!=='unused'){toast('사용이력에서 미사용을 선택하세요.');return;}state.applied={...state.filters,keyword:state.filters.keyword.trim()};state.queried=true;state.selected=[];next();}
function cancelModal(){const m=state.modal;if(!m)return;if(m.kind==='success')return;if(m.kind==='restart'){state.modal=m.previous||null;save();render();return;}if(m.kind==='confirm'&&m.operation==='delete'){state.step=at('delete-submit');state.modal={kind:'delete',title:'회원 삭제',returnStep:at('delete')};save();render();return;}state.step=m.returnStep;state.modal=null;save();render();}
async function action(key,el){if(key==='outside'){toast('현재 실습은 학생 회원 관리 범위입니다.');return;}if(key==='expand'){state.expanded=!state.expanded;save();render();return;}if(key==='one-page'){toast('현재 가상 학생 목록은 한 페이지에 표시됩니다.');return;}if(key==='restart'){openModal({kind:'restart',title:'학생 실습을 처음부터 시작할까요?',text:'학생 실습 진행과 가상 학생 데이터가 초기화됩니다.',previous:state.modal},false);return;}if(key==='restart-now'){state=initial();save();render();return;}if(key==='modal-cancel'){cancelModal();return;}
if(state.modal?.kind==='restart'&&key==='modal-confirm'){state=initial();save();render();return;}
if(key==='modal-confirm'){const m=state.modal;if(!m)return;if(m.kind==='success'){if(cur()?.key!==m.key){toast('현재 안내를 확인해 주세요.');return;}state.modal=null;if(m.after==='list'){state.page='list';clearFilters();state.applied={};state.queried=true;}if(m.after==='detail'){state.page='detail';state.editing=false;state.draft={...state.students.find(t=>t.id==='new')};}if(m.after==='pw-edit'){state.editing=true;}if(m.key==='ack-bulk-pw'){state.selected=[];state.force=false;}next();return;}
if(m.kind==='confirm'&&m.operation==='transfer'&&is('transfer-confirm')){state.students.filter(t=>state.selected.includes(t.id)).forEach(t=>t.transferred=true);state.selected=[];success('전출 처리되었습니다.','조수아·정하준 학생이 재학생 목록에서 제외되었습니다.','ack-transfer','list');return;}
if(m.kind==='confirm'&&m.operation==='delete'&&is('delete-confirm')){const targets=state.students.filter(t=>state.selected.includes(t.id));if(targets.some(t=>t.use)||!state.deleteAgreed||!state.deleteReason.trim()){toast('미사용 계정과 삭제 사유·동의를 확인하세요.');return;}targets.forEach(t=>{t.deleted=true;t.deleteReason=state.deleteReason.trim();});state.selected=[];success('회원 삭제가 완료되었습니다.','가상 미사용 계정 최라온이 삭제되었습니다.','ack-delete');return;}}
if(key==='id-assign'&&state.modal?.kind==='id'){if(/\d/.test(state.modal.base||'')){$('modal-error').textContent='숫자는 입력할 수 없습니다. 영문 아이디만 입력해 주세요.';return;}const expected=state.modal.bulk?'bulk-id-assign':'id-assign';if(!guard(expected))return;try{state.modal.result=uniqueEmail(state.modal.base.trim().toLowerCase(),state.modal.id);next();}catch(e){$('modal-error').textContent=e.message;}return;}
if(key==='id-apply'&&state.modal?.kind==='id'){const m=state.modal;if(!guard(m.bulk?'bulk-id-apply':'id-apply'))return;if(!m.result){$('modal-error').textContent='번호 채번을 먼저 클릭하세요.';return;}if(m.bulk)state.bulk.find(t=>t.id===m.id).email=m.result;else state.draft.email=m.result;state.modal=null;next();return;}
if((key==='fill-password'||key==='fill-password-check')&&state.modal?.kind==='password'){const m=state.modal,checking=key==='fill-password-check',expected=(m.bulk?'bulk-pw-':'pw-')+(checking?'check':'value'),field=checking?'passwordCheck':'password',id=checking?'password-check':'password-value',value=m.bulk?'Practice456!':'Practice123!';if(!is(expected)){if(m[field]!==value)guard(expected);return;}m[field]=value;$(id).value=value;$('modal-error').textContent='';expectedInput(id,value);return;}
if(key==='password-submit'&&state.modal?.kind==='password'){const m=state.modal;if(!guard(m.bulk?'bulk-pw-submit':'pw-submit'))return;const error=passwordError(m.password||'',m.passwordCheck||'');if(error){$('modal-error').textContent=error;return;}const ids=m.bulk?[...state.selected]:['new'];state.students.filter(t=>ids.includes(t.id)).forEach(t=>{t.password=m.password;t.forceChange=m.bulk?state.force:false;t.passwordChanged=true;});if(!m.bulk){state.draft.password=m.password;state.draft.forceChange=false;state.draft.passwordChanged=true;}success('비밀번호가 변경되었습니다.',m.bulk?'선택한 두 학생에게 비밀번호와 다음 로그인 변경 설정이 적용되었습니다.':'김민서 학생의 실습용 비밀번호가 변경되었습니다.',m.bulk?'ack-bulk-pw':'ack-pw',m.bulk?'list':'pw-edit');return;}
if(key==='delete-submit'&&state.modal?.kind==='delete'){if(!guard('delete-submit'))return;if(!state.deleteReason.trim()||!state.deleteAgreed){$('modal-error').textContent='삭제 사유를 작성하고 안내에 동의하세요.';return;}openModal({kind:'confirm',title:'회원 삭제를 확정할까요?',text:'선택한 학생: 최라온\n삭제 사유: '+state.deleteReason.trim(),operation:'delete'});return;}
if(state.modal){toast('열려 있는 창의 안내를 먼저 완료하세요.');return;}
if((key==='template'||key==='sample')&&state.page==='bulk'){const filename=key==='template'?'학생_일괄등록_양식.xlsx':'학생_일괄등록_연습.xlsx';state.downloads.push(filename);if(is(key)){state.step++;inputNext();}else save();toast('엑셀 파일 다운로드를 요청했습니다. 브라우저의 다운로드 목록을 확인하세요.');return;}
if(key==='load-demo'){if(!guard('upload'))return;if(!state.bulkConsent){toast('학생 개인정보 활용 안내에 동의해 주세요.');return;}state.bulk=bulkObjects([bulkHeaders,...practiceRows]);state.bulkFile='학생_일괄등록_연습.xlsx (가상 명단 불러옴)';state.fileError='';next();return;}
if(key==='clear'){clearFilters();if(is('find-search'))state.step=at('find-name');if(is('unused-search'))state.step=at('unused');save();render();return;}
if(key.startsWith('date-')){const n={today:0,month:1,quarter:3,half:6}[key.slice(5)];if(n===undefined){state.filters.from='';state.filters.to='';}else{const d=new Date('2026-10-18T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-n);state.filters.from=d.toISOString().slice(0,10);state.filters.to='2026-10-18';}save();render();return;}
const map={search:is('search-first')?'search-first':is('find-search')?'find-search':'unused-search',save:state.page==='new'?'save-new':'save-edit'};if(!guard(map[key]||key))return;
switch(key){case'nav':state.page='list';next();break;case'search':runSearch();break;case'new':state.draft=emptyDraft();state.page='new';next();break;
case'generate':try{state.draft.email=uniqueEmail(idBase(state.draft.surname,state.draft.given));next();}catch(e){toast(e.message);}break;
case'id-edit':openModal({kind:'id',title:'아이디 수정',oldEmail:state.draft.email,base:'',result:'',bulk:false});break;
case'save':{const error=validDraft(state.draft);if(error){toast(error);return;}if(state.page==='new'){if(state.students.some(t=>!t.deleted&&!t.transferred&&t.grade===state.draft.grade&&t.class===state.draft.class&&t.number===state.draft.number)){toast('학년·반·번호가 중복됩니다.');return;}const d={...state.draft,id:'new',joined:'2026.10.18 10:00',use:false};d.password=d.email.split('@')[0]+d.grade+d.number;state.students.push(d);success('등록되었습니다.','김민서 학생 계정이 생성되었습니다.\n초기 비밀번호: '+d.password,'ack-new','list');}else{const t=state.students.find(t=>t.id===state.detailId);Object.assign(t,state.draft,{modified:true});state.editing=false;success('저장되었습니다.','김민서 학생의 반이 3반으로 변경되었습니다.','ack-edit','detail');}break;}
case'bulk':state.page='bulk';state.bulk=[];state.bulkConsent=false;state.bulkFile='';next();break;
case'bulk-generate':if(!state.bulkConsent||state.bulk.length!==3){toast('동의와 연습용 명단 3명을 확인하세요.');return;}state.bulk.forEach(t=>t.email=uniqueEmail(idBase(t.surname,t.given),t.id));next();break;
case'bulk-id-edit':if(el.dataset.id!=='b1'){toast('첫 번째 조수아 학생의 수정하기를 클릭하세요.');return;}openModal({kind:'id',title:'아이디 수정',oldEmail:state.bulk[0].email,base:'',result:'',bulk:true,id:'b1'});break;
case'bulk-register':if(!state.bulkConsent||state.bulk.length!==3||state.bulk.some(t=>!t.email)){toast('학생 정보와 아이디를 확인하세요.');return;}if(state.bulk.some(t=>state.students.some(x=>x.email===t.email||(!x.deleted&&!x.transferred&&x.grade===t.grade&&x.class===t.class&&x.number===t.number)))){toast('학적정보 또는 아이디가 중복됩니다.');return;}state.bulk.forEach(t=>state.students.push({...t,password:t.email.split('@')[0]+t.grade+t.number,use:false,joined:'2026.10.18 10:05',transferred:false}));success('일괄 등록되었습니다.','조수아·정하준·최지우 학생 계정이 생성되었습니다.','ack-bulk','list');break;
case'detail':if(el.dataset.id!=='new'){toast('김민서 학생의 상세 정보를 확인하세요.');return;}state.detailId='new';state.draft={...state.students.find(t=>t.id==='new')};state.page='detail';next();break;
case'edit':state.editing=true;next();break;
case'pw-single':openModal({kind:'password',title:'학생 비밀번호 변경',bulk:false,password:'',passwordCheck:''});break;
case'back':state.page='list';state.editing=false;clearFilters();state.queried=true;next();break;
case'pw-bulk':if(state.selected.length!==2||!state.selected.includes('s2')||!state.selected.includes('s3')){toast('이다온·박하람 두 학생을 선택하세요.');return;}openModal({kind:'password',title:'비밀번호 일괄 변경',bulk:true,password:'',passwordCheck:''});break;
case'export':{const rows=filtered();await downloadXlsx('서울연습초등학교_학생목록.xlsx',[['사용이력','소속명','학년','반','번호','이름','아이디','가입일시'],...rows.map(t=>[t.use?'사용':'미사용',SCHOOL,t.grade,t.class,t.number,name(t),t.email,t.joined])]);state.selected=[];toast('현재 조회된 학생 '+rows.length+'명의 엑셀 파일을 다운로드했습니다.');next();break;}
case'transfer':if(state.selected.length!==2||!state.selected.includes('b1')||!state.selected.includes('b2')){toast('조수아·정하준 두 학생만 선택하세요.');return;}openModal({kind:'confirm',title:'일괄 전출처리 확인',text:`선택된 ${state.selected.length}명의 학생을 전출처리하시겠습니까?`,count:state.selected.length,operation:'transfer'});break;
case'delete':if(state.applied.use!=='unused'||state.selected.length!==1||state.selected[0]!=='s4'){toast('미사용으로 조회한 뒤 최라온 학생 한 명을 선택하세요.');return;}state.deleteReason='';state.deleteAgreed=false;openModal({kind:'delete',title:'회원 삭제'});break;}}
const xml=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
function columnName(n){let s='';do{s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)-1;}while(n>=0);return s;}
async function workbookBlob(rows,template=false){const zip=new JSZip(),ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';const cells=rows.map((r,i)=>`<row r="${i+1}" ht="${i===0?32:22}" customHeight="1">${r.map((v,j)=>`<c r="${columnName(j)}${i+1}" t="inlineStr" s="${i===0?1:0}"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('');
zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
zip.file('xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${template?'학생 일괄 등록 양식':'학생 목록'}" sheetId="1" r:id="rId1"/></sheets></workbook>`);
zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
zip.file('xl/styles.xml',`<?xml version="1.0"?><styleSheet xmlns="${ns}"><fonts count="2"><font><sz val="11"/><name val="Malgun Gothic"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Malgun Gothic"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF3158DE"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="49" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs></styleSheet>`);
zip.file('xl/worksheets/sheet1.xml',`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="${ns}"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="22"/><cols>${rows[0].map((h,i)=>`<col min="${i+1}" max="${i+1}" width="${h.includes('아이디')||h.includes('이메일')?32:h.length>8?25:17}" customWidth="1"/>`).join('')}</cols><sheetData>${cells}</sheetData><autoFilter ref="A1:${columnName(rows[0].length-1)}${Math.max(rows.length,1)}"/></worksheet>`);
return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'});}
async function downloadXlsx(filename,rows,template=false){const blob=await workbookBlob(rows,template),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);state.downloads.push(filename);save();}
function parseXml(text){const d=new DOMParser().parseFromString(text,'application/xml');if(d.querySelector('parsererror'))throw Error('엑셀 파일의 형식이 올바르지 않습니다.');return d;}
async function readXlsx(file){const zip=await JSZip.loadAsync(await file.arrayBuffer());let path='xl/worksheets/sheet1.xml';const wb=zip.file('xl/workbook.xml'),rels=zip.file('xl/_rels/workbook.xml.rels');if(wb&&rels){const doc=parseXml(await wb.async('string')),rid=doc.getElementsByTagName('sheet')[0]?.getAttribute('r:id');const rdoc=parseXml(await rels.async('string'));const rel=[...rdoc.getElementsByTagName('Relationship')].find(x=>x.getAttribute('Id')===rid);if(rel){const target=rel.getAttribute('Target');path=target.startsWith('/')?target.slice(1):'xl/'+target;}}if(!zip.file(path))throw Error('엑셀 시트를 찾을 수 없습니다.');let shared=[];if(zip.file('xl/sharedStrings.xml')){const d=parseXml(await zip.file('xl/sharedStrings.xml').async('string'));shared=[...d.getElementsByTagName('si')].map(s=>[...s.getElementsByTagName('t')].map(t=>t.textContent).join(''));}const doc=parseXml(await zip.file(path).async('string'));return [...doc.getElementsByTagName('row')].map(row=>{const out=[];[...row.getElementsByTagName('c')].forEach(c=>{const ref=c.getAttribute('r')||'A1',col=ref.match(/[A-Z]+/)[0];let index=0;for(const ch of col)index=index*26+ch.charCodeAt(0)-64;const t=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent||'';out[index-1]=t==='s'?shared[Number(v)]:t==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):v;});return out;});}
function parseCsv(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
function bulkObjects(rows){const headers=rows[0]?.map(v=>String(v||'').replace(/^\*/,'').trim())||[];for(const key of ['학년','반','번호','성','이름','전체이름','성별','생년월일'])if(!headers.includes(key))throw Error('필수 열이 없습니다: '+key);const data=rows.slice(1).filter(r=>r.some(v=>String(v||'').trim()));if(data.length!==3)throw Error('제공된 연습용 파일의 가상 학생 3명을 업로드해 주세요.');const seen=new Set();return data.map((r,i)=>{const get=k=>String(r[headers.indexOf(k)]??'').trim();for(const k of ['학년','반','번호','성','이름','전체이름','성별','생년월일'])if(!get(k))throw Error((i+2)+'행의 '+k+'을 확인하세요.');let birth=get('생년월일');if(/^\d{8}$/.test(birth))birth=birth.slice(0,4)+'-'+birth.slice(4,6)+'-'+birth.slice(6,8);else if(/^\d{5}$/.test(birth))birth=new Date(Date.UTC(1899,11,30)+Number(birth)*86400000).toISOString().slice(0,10);if(!validBirth(birth))throw Error((i+2)+'행의 생년월일이 올바르지 않습니다.');const full=get('성')+get('이름');if(full!==get('전체이름'))throw Error((i+2)+'행의 전체이름이 성·이름과 일치하지 않습니다.');if(full!==['조수아','정하준','최지우'][i])throw Error('제공된 연습용 가상 명단을 그대로 선택해 주세요.');const key=[get('학년'),get('반'),get('번호')].join('-');if(seen.has(key))throw Error('학년·반·번호가 중복됩니다.');seen.add(key);if(get('학년')!=='4'||get('반')!=='2'||get('번호')!==String(22+i))throw Error('연습 명단의 학년·반·번호를 확인하세요.');if(!['남자','여자','남','여','M','F'].includes(get('성별')))throw Error('성별 값을 확인하세요.');return {id:'b'+(i+1),surname:get('성'),given:get('이름'),email:'',birth,gender:['남자','남','M'].includes(get('성별'))?'M':'F',grade:get('학년'),class:get('반'),number:get('번호'),consent:'일괄등록_사전동의확인',method:'phone',contact:get('휴대전화번호')||'01000000000',agree:true,use:false};});}
async function uploadFile(file){if(!guard('upload'))return;if(!state.bulkConsent){toast('개인정보 활용 안내 확인 및 동의를 체크하세요.');return;}if(!file)return;if(file.size>3*1024*1024){toast('3MB 이하의 연습용 파일을 선택하세요.');return;}try{let rows;if(/\.xlsx$/i.test(file.name))rows=await readXlsx(file);else if(/\.csv$/i.test(file.name))rows=parseCsv((await file.text()).replace(/^\uFEFF/,''));else throw Error('엑셀 .xlsx 또는 CSV 파일을 선택하세요.');state.bulk=bulkObjects(rows);state.bulkFile=file.name;state.fileError='';next();}catch(e){state.fileError=e.message||'파일을 불러오지 못했습니다.';save();render();}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)Promise.resolve(action(el.dataset.action,el)).catch(error=>toast(error.message||'다시 시도해 주세요.'));});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.draft&&el.type!=='radio'){state.draft[el.dataset.draft]=el.value;expectedInput(el.id,el.value);save();}else if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;expectedInput(el.id,el.value);save();}else if(el.dataset.modal&&state.modal){if(el.dataset.modal==='deleteReason')state.deleteReason=el.value;else{state.modal[el.dataset.modal]=el.value;if(el.dataset.modal==='base'){state.modal.result='';if($('id-result'))$('id-result').textContent='';if($('id-assigned-note'))$('id-assigned-note').textContent='';if(is('id-apply')||is('bulk-id-apply'))state.step=at(state.modal.bulk?'bulk-id-base':'id-base');}}expectedInput(el.id,el.value);$('modal-error').textContent='';save();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='bulk-file'){uploadFile(el.files?.[0]);return;}if(el.dataset.select){const id=el.dataset.select,validKey={s2:'select-s2',s3:'select-s3',b1:'transfer-b1',b2:'transfer-b2',s4:'select-unused'}[id];if(!guard(validKey)){el.checked=state.selected.includes(id);return;}if(!el.checked){el.checked=true;return;}if(!state.selected.includes(id))state.selected.push(id);next();return;}if(el.dataset.change==='all'){el.checked=false;toast('지정된 실습 학생을 한 명씩 선택하세요.');return;}if(el.dataset.change==='bulk-consent'){if(!guard('bulk-consent')){el.checked=state.bulkConsent;return;}state.bulkConsent=el.checked;if(el.checked)next();return;}if(el.dataset.change==='force'){if(!guard('force-change')){el.checked=state.force;return;}state.force=el.checked;if(el.checked)next();return;}if(el.dataset.change==='delete-agree'){if(!guard('delete-agree')){el.checked=state.deleteAgreed;return;}state.deleteAgreed=el.checked;if(el.checked)next();return;}if(el.dataset.draft){const k=el.dataset.draft;state.draft[k]=['agree','use'].includes(k)?el.value==='yes':el.value;if(k==='gender'&&is('gender')&&el.value==='F')next();else if(k==='agree'&&is('agree')&&el.value==='yes')next();else{expectedInput(el.id,el.value);save();}return;}if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;if(el.dataset.filter==='use'&&is('unused')&&el.value==='unused')next();else{expectedInput(el.id,el.value);save();}}});
document.addEventListener('keydown',e=>{if(state.modal?.kind==='password'&&(e.key==='Enter'||e.key===' ')&&['fill-password','fill-password-check'].includes(e.target.dataset.action)){e.preventDefault();action(e.target.dataset.action).catch(error=>toast(error.message));return;}if(state.modal){if(e.key==='Escape'){e.preventDefault();cancelModal();return;}if(e.key==='Tab'){const nodes=[...$('modal-root').querySelectorAll('input,textarea,button')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.key==='Enter'&&e.target.dataset.filter){e.preventDefault();action('search').catch(error=>toast(error.message));}});
$('hint-toggle').addEventListener('click',()=>{state.hints=!state.hints;save();highlight();});$('restart').addEventListener('click',()=>action('restart'));
render();
